import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    s = input[1]

    open_count = 0
    close_needed = 0
    result = []

    for char in s:
        if char == '(':
            open_count += 1
            result.append('(')
        elif char == ')':
            if open_count > 0:
                open_count -= 1
            else:
                close_needed += 1
            result.append(')')
        else:  # char == '?'
            if close_needed > 0:
                close_needed -= 1
                result.append(')')
            else:
                open_count += 1
                result.append('(')

    if open_count != close_needed:
        print(":(")
    else:
        print("".join(result))

main()
